    var sy = scale(yt.min, yt.max, m.t + ih, m.t);
    var b = "";
    // gridlines (recessive, horizontal only)
    if (o.grid !== false) yt.ticks.forEach(function (v) { b += L(m.l, sy(v), m.l + iw, sy(v), { stroke: GRID, w: 1 }); });
    // spines
